65 What is the output of the following program?

class Shape:
    def area(self):
        return 0

class Square(Shape):
    def __init__(self, s):
        self.s = s

    def area(self):
        return self.s * self.s

class Rectangle(Shape):
    def __init__(self, l, w):
        self.l = l
        self.w = w

    def area(self):
        return self.l * self.w

for sh in [Square(3), Rectangle(2, 5), Shape()]:
    print(sh.area())

